8	/**
9	 * The entry step of {@code POST /api/owners}: honours an optional {@code Idempotency-Key} header.
10	 *
11	 * <p>When the request carries a key already seen (a repeated create), the branch short-circuits to
12	 * {@code existing}, which loads and returns the owner originally created for that key with 200 —
13	 * no duplicate is created. Otherwise (no key, or a new key) the {@code create} branch runs the
14	 * normal validate-through-respond pipeline; the key, if any, is recorded once the owner is saved by
15	 * {@link RecordOwnerIdempotency}.
16	 *
17	 * <p>This runs before {@link ValidateOwner} reads the body, so a duplicate retry never binds
18	 * {@code @RequestBody} — only the taken branch does.
19	 */
20	public class CheckOwnerIdempotency {
21	
22	    @FunctionalInterface
23	    public interface ExistingOwnerFlow {
24	        void flow(Integer ownerId);
25	    }
26	
27	    @FunctionalInterface
28	    public interface CreateOwnerFlow {
29	        void flow();
30	    }
31	
32	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey,
33	            IdempotencyStore idempotencyStore, @Flow("existing") ExistingOwnerFlow existing,
34	            @Flow("create") CreateOwnerFlow create) {
35	        Integer existingOwnerId = idempotencyStore.find(idempotencyKey);
36	        if (existingOwnerId != null) {
37	            existing.flow(existingOwnerId);
38	            return;
39	        }
40	        create.flow();
41	    }
42	}
