146	/**
147	 * Rejects an owner whose email domain is on the disposable-domain blocklist. Email is optional, so
148	 * an absent (null/blank) email is skipped; a present but syntactically invalid address is already
149	 * rejected 400 by the {@code @Email} constraint at {@link ValidateOwner}. Runs after
150	 * {@link NormalizeOwnerEmail} has lower-cased the address, so the domain comparison is
151	 * case-insensitive. A blocklisted domain is rejected 400 via {@link DisposableEmailDomainException}.
152	 */
153	public class ValidateOwnerEmailDomain {
154	
155	    /** Disposable email domains that are not accepted for owner registration. */
156	    private static final Set<String> BLOCKED_DOMAINS =
157	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
158	
159	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
160	        String email = request.getEmail();
161	        if (email == null) {
162	            return; // optional when absent
163	        }
164	        int at = email.lastIndexOf('@');
165	        if (at < 0 || at == email.length() - 1) {
166	            return; // no domain part; syntactic validity is enforced by @Email at ValidateOwner
167	        }
168	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
169	        if (BLOCKED_DOMAINS.contains(domain)) {
170	            throw new DisposableEmailDomainException(
171	                "Email domain " + domain + " is not accepted (disposable-domain blocklist)");
172	        }
