176	package org.springframework.samples.petclinic.rest.function.owner;
177	
178	import java.util.Locale;
179	
180	import net.officefloor.plugin.variable.Val;
181	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
182	import org.springframework.samples.petclinic.rest.escalation.InvalidAddressException;
183	
184	/**
185	 * Normalizes the owner's address on create, mutating the validated request in place so later
186	 * steps persist and return the normalized value. Normalization (trim, collapse internal whitespace
187	 * to a single space, upper-case, expand common street-type abbreviations {@code ST -> STREET},
188	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}) applies to whichever address fields are supplied.
189	 *
190	 * <p>The structured form is preferred: when a non-blank {@code addressLine1} is supplied it (and the
191	 * optional {@code addressLine2}) are normalized in place, and the flat {@code address} is set to the
192	 * composed value — the normalized {@code addressLine1}, plus a single space and the normalized
193	 * {@code addressLine2} when {@code addressLine2} is present. Otherwise the flat {@code address} is
194	 * normalized directly. Either way, an address that is blank after normalization is rejected 400 via
195	 * {@link InvalidAddressException}, so a whitespace-only value that passes the raw length constraint
196	 * is still rejected here.
197	 */
198	public class NormalizeOwnerAddress {
199	
200	    public void service(@Val OwnerFieldsDto request) throws InvalidAddressException {
201	        if (OwnerAddresses.hasStructured(request)) {
202	            String normalizedLine1 = normalizeRequired(request.getAddressLine1());
203	            request.setAddressLine1(normalizedLine1);
204	            String normalizedLine2 = null;
205	            String line2 = request.getAddressLine2();
206	            if (line2 != null && !line2.isBlank()) {
207	                normalizedLine2 = normalize(line2);
208	                request.setAddressLine2(normalizedLine2);
209	            }
210	            request.setAddress(OwnerAddresses.compose(normalizedLine1, normalizedLine2));
211	        }
212	        else {
213	            request.setAddress(normalizeRequired(request.getAddress()));
214	        }
215	    }
216	
217	    /**
218	     * Normalizes a supplied address value and rejects it 400 when it is blank after normalization,
219	     * so a whitespace-only value that passes the raw length constraint is still rejected here.
220	     */
221	    private static String normalizeRequired(String value) throws InvalidAddressException {
222	        String normalized = normalize(value);
223	        if (normalized.isEmpty()) {
224	            throw new InvalidAddressException("Address must not be blank after normalization");
225	        }
226	        return normalized;
227	    }
228	
229	    /**
230	     * The single source of truth for the normalized form of an address: trimmed with internal
231	     * whitespace collapsed, upper-cased, and common street-type abbreviations expanded. Returns the
232	     * empty string for a null or blank input. Shared with {@link AssignOwnerHousehold} so the request
233	     * side and the shared household id are compared on identical normalized text.
234	     */
235	    static String normalize(String value) {
236	        if (value == null) {
237	            return "";
238	        }
239	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
240	        if (collapsed.isEmpty()) {
241	            return "";
242	        }
243	        String[] tokens = collapsed.split(" ");
244	        StringBuilder sb = new StringBuilder(collapsed.length());
245	        for (int i = 0; i < tokens.length; i++) {
246	            if (i > 0) {
247	                sb.append(' ');
248	            }
249	            sb.append(expand(tokens[i]));
250	        }
251	        return sb.toString();
252	    }
253	
254	    private static String expand(String token) {
255	        switch (token) {
256	            case "ST":
257	                return "STREET";
258	            case "RD":
259	                return "ROAD";
260	            case "AVE":
261	                return "AVENUE";
262	            default:
263	                return token;
264	        }
265	    }
266	}
