268	package org.springframework.samples.petclinic.rest.function.owner;
269	
270	import net.officefloor.plugin.variable.Val;
271	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
272	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
273	
274	/**
275	 * Normalizes the owner's telephone on create into E.164 form, mutating the validated request in
276	 * place so later steps store and return the E.164 value. Spaces, dashes and brackets are stripped.
277	 * A leading '+' and its country code are kept as given; otherwise country code '+61' is assumed and
278	 * a single leading '0' is dropped from the national digits (so {@code 0412 345 678} becomes
279	 * {@code +61412345678}). The result must carry 8 to 15 digits after the '+', and its national
280	 * number (the digits after the country code) must match the length that country requires — '+61'
281	 * needs 9 national digits, '+1' needs 10. Anything that cannot form valid E.164 is rejected 400 via
282	 * {@link InvalidTelephoneException}.
283	 */
284	public class NormalizeOwnerTelephone {
285	
286	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
287	        request.setTelephone(toE164(request.getTelephone()));
288	    }
289	
290	    /**
291	     * The single source of truth for what "same telephone" means: converts a raw telephone into its
292	     * E.164 form. Spaces, dashes and brackets are removed; a leading '+' and country code are kept,
293	     * otherwise '+61' is assumed and a single leading '0' is dropped from the national digits. The
294	     * digits after the '+' must number 8 to 15, no other characters may remain, and the national
295	     * number must have the length the country code requires ('+61' => 9, '+1' => 10). The E.164 value
296	     * is what is stored and returned; it also composes the display-only
297	     * {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey() identityKey} but no
298	     * longer participates in duplicate detection (which is household-based).
299	     *
300	     * @throws InvalidTelephoneException if the value cannot form valid E.164.
301	     */
302	    static String toE164(String telephone) throws InvalidTelephoneException {
303	        if (telephone == null) {
304	            throw invalid();
305	        }
306	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
307	        String digits;
308	        if (cleaned.startsWith("+")) {
309	            digits = cleaned.substring(1);
310	        }
311	        else {
312	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
313	            digits = "61" + national;
314	        }
315	        if (!digits.matches("\\d{8,15}")) {
316	            throw invalid();
317	        }
318	        checkNationalLength(digits);
319	        return "+" + digits;
320	    }
321	
322	    /**
323	     * Rejects a number whose national number (the digits after the country code) does not match the
324	     * length that country code requires: '+61' => 9 national digits, '+1' => 10. Country codes not
325	     * listed here are left to the generic 8-to-15 digit rule.
326	     */
327	    private static void checkNationalLength(String digits) throws InvalidTelephoneException {
328	        String countryCode;
329	        int requiredNationalLength;
330	        if (digits.startsWith("61")) {
331	            countryCode = "61";
332	            requiredNationalLength = 9;
333	        }
334	        else if (digits.startsWith("1")) {
335	            countryCode = "1";
336	            requiredNationalLength = 10;
337	        }
338	        else {
339	            return;
340	        }
341	        int nationalLength = digits.length() - countryCode.length();
342	        if (nationalLength != requiredNationalLength) {
343	            throw new InvalidTelephoneException("Telephone with country code '+" + countryCode
344	                    + "' must have " + requiredNationalLength + " national digits, but had "
345	                    + nationalLength);
346	        }
347	    }
348	
349	    private static InvalidTelephoneException invalid() {
350	        return new InvalidTelephoneException(
351	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
352	    }
353	}
