355	package org.springframework.samples.petclinic.rest.function.owner;
356	
357	import java.util.Map;
358	
359	import net.officefloor.plugin.variable.Val;
360	import org.springframework.samples.petclinic.model.Owner;
361	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
362	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
363	
364	/**
365	 * Validates the owner's postcode against the city's region when a postcode is present. The 4-digit
366	 * shape is already enforced by the {@code OwnerFieldsDto} bean-validation pattern (a malformed
367	 * postcode is rejected 400 before this step); here the value is range-checked against the fixed
368	 * city-to-region postcode table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
369	 * region accepts any 4-digit postcode. When absent, postcode is optional and skipped entirely so the
370	 * request contract stays backward-compatible. An out-of-range postcode is rejected 400 via
371	 * {@link InvalidPostcodeException}.
372	 */
373	public class ValidateOwnerPostcode {
374	
375	    /** Region -> inclusive 4-digit postcode range {low, high}. */
376	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
377	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
378	
379	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
380	        String postcode = request.getPostcode();
381	        if (postcode == null || postcode.isEmpty()) {
382	            return; // optional when absent
383	        }
384	        String region = Owner.regionOf(request.getCity());
385	        if (region == null) {
386	            return; // city with no known region accepts any 4-digit postcode
387	        }
388	        int[] range = REGION_POSTCODES.get(region);
389	        int value = Integer.parseInt(postcode); // 4-digit shape guaranteed by the DTO pattern
390	        if (value < range[0] || value > range[1]) {
391	            throw new InvalidPostcodeException(
392	                "Postcode " + postcode + " is not valid for city " + request.getCity());
393	        }
394	    }
395	}
