404	/**
405	 * Rejects creating an owner when the owner's city already holds {@value #CITY_CAPACITY} or more
406	 * owners. A city at capacity is rejected 409 via {@link CityOwnerLimitExceededException}.
407	 */
408	public class CheckOwnerCityCapacity {
409	
410	    static final int CITY_CAPACITY = 50;
411	
412	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
413	            throws CityOwnerLimitExceededException {
414	        String city = request.getCity();
415	        if (countInCity(ownerRepository, city) >= CITY_CAPACITY) {
416	            throw new CityOwnerLimitExceededException(
417	                    "City " + city + " already has " + CITY_CAPACITY + " or more owners");
418	        }
419	    }
420	
421	    /** Existing owners whose city equals {@code city} case-insensitively, backing the 409 gate. */
422	    private static long countInCity(OwnerRepository ownerRepository, String city) {
423	        return ownerRepository.findAll().stream()
424	                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
425	                .count();
426	    }
427	}
