492	/**
493	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
494	 * region code derived from the owner's postcode (see {@link Owner#regionOfPostcode(String)}, or
495	 * {@code UNKNOWN} when the postcode maps to no known region) and HASH8 is the first 8 upper-case hex
496	 * characters of the SHA-256 of the normalized telephone concatenated with the lastName (e.g.
497	 * {@code NSW-3F9A1C7E}). The customer code no longer carries any per-city sequence number. When the
498	 * computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is appended with
499	 * the smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSW-3F9A1C7E-2}). Runs after
500	 * {@link BuildOwner} builds the entity (so the telephone is already in canonical E.164 form) and
501	 * before {@link SaveOwner} persists it, mutating the built owner in place so the saved and returned
502	 * record carries the code. Every value derived from the customer code — the membership number, its
503	 * check digit and the {@link Owner#getLocality() locality} — follows from this region-and-hash
504	 * identity.
505	 */
506	public class AssignOwnerCustomerCode {
507	
508	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
509	        String region = Owner.regionOfPostcode(owner.getPostcode());
510	        if (region == null) {
511	            region = "UNKNOWN";
512	        }
513	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
514	        String base = region + "-" + hash8;
515	        owner.setCustomerCode(deduplicate(base, owner, ownerRepository));
516	    }
517	
518	    /**
519	     * The unique customer code for the owner: {@code base} when no other owner already carries it,
520	     * otherwise {@code base-<n>} with the smallest {@code n} of 2 or more that is not yet taken.
521	     * The owner is not yet persisted, so its own code is excluded by identity.
522	     */
523	    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
524	        Set<String> taken = new HashSet<>();
525	        for (Owner existing : ownerRepository.findAll()) {
526	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
527	                continue;
528	            }
529	            String code = existing.getCustomerCode();
530	            if (code != null) {
531	                taken.add(code);
532	            }
533	        }
534	        if (!taken.contains(base)) {
535	            return base;
536	        }
537	        int n = 2;
538	        while (taken.contains(base + "-" + n)) {
539	            n++;
540	        }
541	        return base + "-" + n;
542	    }
543	
544	    /**
545	     * The first 8 upper-case hex characters of the SHA-256 digest of {@code value}, taken over its
546	     * UTF-8 bytes — i.e. the first 4 digest bytes rendered as hex.
547	     */
548	    private static String sha256Hex8(String value) {
549	        try {
550	            byte[] digest = MessageDigest.getInstance("SHA-256")
551	                    .digest(value.getBytes(StandardCharsets.UTF_8));
552	            StringBuilder sb = new StringBuilder(8);
553	            for (int i = 0; i < 4; i++) {
554	                sb.append(String.format(Locale.ROOT, "%02X", digest[i]));
555	            }
556	            return sb.toString();
557	        }
558	        catch (NoSuchAlgorithmException ex) {
559	            throw new IllegalStateException("SHA-256 not available", ex);
560	        }
561	    }
562	}
