587	package org.springframework.samples.petclinic.rest.function.owner;
588	
589	import java.nio.charset.StandardCharsets;
590	import java.security.MessageDigest;
591	import java.security.NoSuchAlgorithmException;
592	import java.util.Locale;
593	
594	import net.officefloor.plugin.variable.Val;
595	import org.springframework.samples.petclinic.model.Owner;
596	
597	/**
598	 * Assigns the owner's deterministic {@code householdId}: the first 12 (upper-case) hex characters of
599	 * the SHA-256 of {@code normalizedLastName + '|' + postcode}. The id is derived purely from the
600	 * (lastName, postcode) pair, so every owner with the same lastName and postcode receives the same
601	 * value automatically, regardless of creation order and without any repository lookup or opt-in.
602	 *
603	 * <p>Because the household is now keyed on (lastName, postcode), owners sharing that pair are the
604	 * same household. This computed id is the single source of truth the household consumers key off:
605	 * {@link CheckOwnerHouseholdUnique} (the household-duplicate 409 block),
606	 * {@link DetectOwnerPossibleDuplicate} and {@link DeriveOwnerHouseholdSize}. The request's
607	 * {@code sharesHousehold} flag no longer creates the link — the link is implicit in the shared id —
608	 * it only bypasses the duplicate block (see {@link CheckOwnerHouseholdUnique}).
609	 *
610	 * <p>Runs after {@link BuildOwner} has created the entity and before {@link CheckOwnerHouseholdUnique}
611	 * (which sees the resolved {@code householdId}) and {@link SaveOwner} persists it.
612	 */
613	public class AssignOwnerHousehold {
614	
615	    public void service(@Val Owner owner) {
616	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
617	    }
618	
619	    /**
620	     * The single source of truth for an owner's household identity: the first 12 upper-case hex
621	     * characters of the SHA-256 of {@code normalize(lastName) + '|' + postcode}. An absent postcode
622	     * contributes an empty segment. Two owners share a household exactly when this value is equal.
623	     */
624	    static String householdId(String lastName, String postcode) {
625	        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
626	        try {
627	            byte[] digest = MessageDigest.getInstance("SHA-256")
628	                    .digest(input.getBytes(StandardCharsets.UTF_8));
629	            StringBuilder sb = new StringBuilder(12);
630	            for (int i = 0; i < 6; i++) {
631	                sb.append(String.format("%02x", digest[i]));
632	            }
633	            return sb.toString().toUpperCase(Locale.ROOT);
634	        }
635	        catch (NoSuchAlgorithmException ex) {
636	            throw new IllegalStateException("SHA-256 not available", ex);
637	        }
638	    }
639	
640	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
641	    static String normalize(String value) {
642	        if (value == null) {
643	            return "";
644	        }
645	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
646	    }
647	}
