649	package org.springframework.samples.petclinic.rest.function.owner;
650	
651	import net.officefloor.plugin.variable.Val;
652	import org.springframework.samples.petclinic.model.Owner;
653	import org.springframework.samples.petclinic.repository.OwnerRepository;
654	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
655	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
656	
657	/**
658	 * The duplicate check for creating an owner: rejects 409 when the new owner would join an existing
659	 * household — that is, when an existing owner shares the new owner's computed
660	 * {@link Owner#getHouseholdId() householdId} (owners with the same lastName and postcode are the
661	 * same household). Because the household is keyed on (lastName, postcode), a second such owner is a
662	 * household duplicate.
663	 *
664	 * <p>The request's {@code sharesHousehold} flag is the sole bypass: when set, the owner is being
665	 * created as a <em>declared</em> household member, so the block is skipped and the owner is created
666	 * despite the collision. It no longer creates the household link — the link is implicit in the
667	 * shared {@code householdId} assigned by {@link AssignOwnerHousehold}.
668	 *
669	 * <p>Runs after {@link BuildOwner} and {@link AssignOwnerHousehold} have produced the entity and
670	 * resolved its {@code householdId}. The new owner is not yet persisted, so
671	 * {@link OwnerRepository#findAll()} yields only the other owners.
672	 */
673	public class CheckOwnerHouseholdUnique {
674	
675	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
676	            throws DuplicateHouseholdException {
677	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
678	            return; // declared household member: bypass the duplicate block
679	        }
680	        String householdId = owner.getHouseholdId();
681	        if (householdId == null) {
682	            return;
683	        }
684	        for (Owner existing : ownerRepository.findAll()) {
685	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
686	                continue;
687	            }
688	            if (existing.isDeleted()) {
689	                continue; // soft-deleted owners are ignored by the duplicate check
690	            }
691	            if (householdId.equals(existing.getHouseholdId())) {
692	                throw new DuplicateHouseholdException(
693	                        "An owner in the same household already exists");
694	            }
695	        }
696	    }
697	}
