776	package org.springframework.samples.petclinic.rest.function.owner;
777	
778	import net.officefloor.plugin.variable.Val;
779	import org.springframework.samples.petclinic.model.Owner;
780	import org.springframework.samples.petclinic.repository.OwnerRepository;
781	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
782	
783	/**
784	 * Flags the new owner as a possible (soft) duplicate, keyed off the computed
785	 * {@link Owner#getHouseholdId() householdId}: an owner is a possible duplicate when an earlier owner
786	 * shares its household (same lastName and postcode).
787	 *
788	 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold} true — is never
789	 * flagged: it deliberately joins the household, so it is not a suspected duplicate. Any other owner
790	 * sharing an existing household has already been rejected 409 by {@link CheckOwnerHouseholdUnique},
791	 * so in practice this leaves {@code possibleDuplicate} false; keeping the check here keys the soft
792	 * signal off the same household id as the hard block.
793	 *
794	 * <p>Runs after {@link BuildOwner}/{@link AssignOwnerHousehold} and before {@link SaveOwner},
795	 * scanning only pre-existing (already persisted) owners — the new owner has no id yet and is skipped.
796	 * The earliest such match (lowest id) is recorded: {@code possibleDuplicate} is set true and
797	 * {@code possibleDuplicateOf} to that owner's id; otherwise {@code possibleDuplicate} is false and
798	 * {@code possibleDuplicateOf} is left null. Both are stored on the built owner so the saved and
799	 * returned record carries them.
800	 */
801	public class DetectOwnerPossibleDuplicate {
802	
803	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
804	        Owner match = null;
805	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
806	            String householdId = owner.getHouseholdId();
807	            if (householdId != null) {
808	                for (Owner existing : ownerRepository.findAll()) {
809	                    if (existing.getId() == null
810	                            || existing.getId().equals(owner.getId())) {
811	                        continue;
812	                    }
813	                    if (existing.isDeleted()) {
814	                        continue; // soft-deleted owners are ignored by the duplicate check
815	                    }
816	                    if (householdId.equals(existing.getHouseholdId())) {
817	                        if (match == null || existing.getId() < match.getId()) {
818	                            match = existing;
819	                        }
820	                    }
821	                }
822	            }
823	        }
824	        if (match != null) {
825	            owner.setPossibleDuplicate(true);
826	            owner.setPossibleDuplicateOf(match.getId());
827	        }
828	        else {
829	            owner.setPossibleDuplicate(false);
830	            owner.setPossibleDuplicateOf(null);
831	        }
832	    }
833	}
