package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Rejects a supplied registration date that is later than the server's current date: registration
 * cannot be dated in the future. The date is optional on create (it defaults to today when absent),
 * so an absent date is skipped entirely. A future date is rejected 400 via
 * {@link FutureRegistrationDateException}.
 */
public class ValidateOwnerRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(
                "Registration date " + registrationDate + " must not be later than the current date");
        }
    }
}
===== NormalizeOwnerEmail.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes the owner's optional email so it is stored and returned lower-cased, mutating
 * the validated request in place so later steps persist and return the normalized value.
 * Syntactic validity is enforced declaratively by the {@code @Email} constraint on the
 * request DTO (checked at {@link ValidateOwner}), so a present but invalid address is already
 * rejected 400 before this step runs; a missing (null) email is left untouched.
 */
public class NormalizeOwnerEmail {

    public void service(@Val OwnerFieldsDto request) {
        String email = request.getEmail();
        if (email != null) {
            request.setEmail(normalize(email));
        }
    }

    /**
     * The single source of truth for an email's canonical form: lower-cased. Null-safe so it can
     * canonicalize an existing owner's (possibly absent) stored value. The canonical value is what is
     * stored and returned; it also composes the display-only
     * {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey() identityKey} but no
     * longer participates in duplicate detection (which is household-based).
     */
    static String normalize(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }
}
===== ValidateOwnerEmailDomain.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;

/**
 * Rejects an owner whose email domain is on the disposable-domain blocklist. Email is optional, so
 * an absent (null/blank) email is skipped; a present but syntactically invalid address is already
 * rejected 400 by the {@code @Email} constraint at {@link ValidateOwner}. Runs after
 * {@link NormalizeOwnerEmail} has lower-cased the address, so the domain comparison is
 * case-insensitive. A blocklisted domain is rejected 400 via {@link DisposableEmailDomainException}.
 */
public class ValidateOwnerEmailDomain {

    /** Disposable email domains that are not accepted for owner registration. */
    private static final Set<String> BLOCKED_DOMAINS =
        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
        String email = request.getEmail();
        if (email == null) {
            return; // optional when absent
        }
        int at = email.lastIndexOf('@');
        if (at < 0 || at == email.length() - 1) {
            return; // no domain part; syntactic validity is enforced by @Email at ValidateOwner
        }
        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
        if (BLOCKED_DOMAINS.contains(domain)) {
            throw new DisposableEmailDomainException(
                "Email domain " + domain + " is not accepted (disposable-domain blocklist)");
        }
    }
}
